text:
"use client";

import { cn } from "@/lib/utils";

export function RoleChips({
  roles,
  value,
  onChoose,
  disabled = false,
  variant = "default",
}: {
  roles: string[];
  value: string;
  onChoose: (role: string) => void;
  disabled?: boolean;
  variant?: "default" | "contact-form";
}) {
  if (!roles.length) return null;
  return (
    <div
      role="group"
      aria-label="Role shortcuts"
      className={cn(
        "mt-2.5 flex flex-wrap gap-2",
        variant === "contact-form" && "workspace-mono:gap-1.5",
      )}
    >
      {roles.map((role) => {
        const selected = role === value;
        return (
          <button
            key={role}
            type="button"
            aria-pressed={selected}
            disabled={disabled}
            onClick={() => onChoose(role)}
            className={cn(
              "min-h-10 max-w-full rounded-full border px-3.5 py-1.5 text-left text-[13px] break-words font-semibold",
              selected
                ? "border-[var(--contacts-purple)] bg-[var(--appearance-wash,var(--color-rolechips-detail-1))] text-[var(--contacts-text)]"
                : "border-dashed border-[var(--contacts-strong)] text-[var(--contacts-muted)] hover:bg-[var(--appearance-wash,var(--color-rolechips-detail-2))]",
              variant === "contact-form" &&
                "workspace-mono:min-h-8 workspace-mono:py-[5px] workspace-mono:px-2.5 workspace-mono:text-[11px] workspace-mono:border-solid workspace-mono:rounded-[6px]!",
            )}
          >
            {role}
            {selected && (
              <span aria-hidden="true" className="text-[var(--contacts-pink)]">
                {" "}
                ✓
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
}
